/**
 * Landmark tracking by image matching (pyramidal Lucas–Kanade optical flow).
 *
 * The face-mesh network predicts all points jointly from one image, and on
 * asymmetric expressions it pulls the weak and strong sides towards each
 * other (bench: tools/blender/BENCH.md). Tracking instead follows each rest
 * landmark into the expression image by matching the skin texture around it,
 * so each side moves only as far as its own pixels moved. Pure (no DOM).
 */
import { applySimilarity, fitSimilarity, type Similarity } from '../core/geometry';
import { ALIGNMENT_ANCHORS, CONTOURS } from '../core/landmarks';
import type { FrameObservation, Vec2 } from '../core/types';

export interface Gray {
  w: number;
  h: number;
  /** Row-major intensities 0–255 (Uint8 for stored frames, Float32 inside the pyramid). */
  data: Float32Array | Uint8Array;
  /** Drawn into the fine reference crop (FINE_TRACK, FINE_TASKS). */
  fine?: boolean;
}

/** Luma of RGBA pixels (e.g. ImageData.data). */
export function grayFromRGBA(rgba: ArrayLike<number>, w: number, h: number): Gray {
  const data = new Float32Array(w * h);
  for (let i = 0; i < w * h; i++) data[i] = 0.299 * rgba[4 * i]! + 0.587 * rgba[4 * i + 1]! + 0.114 * rgba[4 * i + 2]!;
  return { w, h, data };
}

function half(g: Gray): Gray {
  const w = Math.max(1, g.w >> 1);
  const h = Math.max(1, g.h >> 1);
  const data = new Float32Array(w * h);
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      const i = 2 * y * g.w + 2 * x;
      data[y * w + x] = (g.data[i]! + g.data[i + 1]! + g.data[i + g.w]! + g.data[i + g.w + 1]!) / 4;
    }
  return { w, h, data };
}

function blur(g: Gray): Gray {
  // Separable [1 2 1]/4, edges clamped: keeps the gradients smooth for LK.
  const { w, h } = g;
  const tmp = new Float32Array(w * h);
  const out = new Float32Array(w * h);
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      const r = y * w;
      tmp[r + x] = (g.data[r + Math.max(0, x - 1)]! + 2 * g.data[r + x]! + g.data[r + Math.min(w - 1, x + 1)]!) / 4;
    }
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++)
      out[y * w + x] = (tmp[Math.max(0, y - 1) * w + x]! + 2 * tmp[y * w + x]! + tmp[Math.min(h - 1, y + 1) * w + x]!) / 4;
  return { w, h, data: out };
}

export function pyramid(g: Gray, levels: number): Gray[] {
  const out = [blur(g)];
  for (let l = 1; l < levels; l++) out.push(blur(half(out[l - 1]!)));
  return out;
}

function sample(g: Gray, x: number, y: number): number {
  const xc = Math.min(g.w - 1.001, Math.max(0, x));
  const yc = Math.min(g.h - 1.001, Math.max(0, y));
  const x0 = Math.floor(xc);
  const y0 = Math.floor(yc);
  const fx = xc - x0;
  const fy = yc - y0;
  const i = y0 * g.w + x0;
  const d = g.data;
  return (d[i]! * (1 - fx) + d[i + 1]! * fx) * (1 - fy) + (d[i + g.w]! * (1 - fx) + d[i + g.w + 1]! * fx) * fy;
}

export interface TrackOptions {
  /** Half window size in pixels (window = 2·half + 1). */
  half: number;
  levels: number;
  iters: number;
}

export const TRACK_DEFAULTS: Readonly<TrackOptions> = Object.freeze({ half: 7, levels: 3, iters: 30 });

export interface TrackResult {
  pts: Vec2[];
  /** Mean absolute intensity residual in the window after convergence (0–255). */
  residual: number[];
  /** Smaller eigenvalue of the window's gradient matrix per pixel (texture strength; ~0 = flat or a straight edge). */
  minEig: number[];
}

/**
 * Tracks `pts` from image A to image B. `guess` (same length) is the expected position in B
 * (e.g. the rest point moved by the head motion); LK refines the local displacement from there.
 */
export function trackPoints(A: Gray[], B: Gray[], pts: readonly Vec2[], guess: readonly Vec2[], opt: TrackOptions = TRACK_DEFAULTS): TrackResult {
  const levels = Math.min(opt.levels, A.length, B.length);
  const out: Vec2[] = [];
  const residual: number[] = [];
  const minEig: number[] = [];
  let eig = 0;
  const n = (2 * opt.half + 1) ** 2;
  const ix = new Float32Array(n);
  const iy = new Float32Array(n);
  const ia = new Float32Array(n);
  for (const [k, p] of pts.entries()) {
    const top = 2 ** (levels - 1);
    let gx = (guess[k]!.x - p.x) / top;
    let gy = (guess[k]!.y - p.y) / top;
    let vx = 0;
    let vy = 0;
    let res = 0;
    for (let L = levels - 1; L >= 0; L--) {
      const a = A[L]!;
      const b = B[L]!;
      const s = 2 ** L;
      const px = p.x / s;
      const py = p.y / s;
      let gxx = 0;
      let gxy = 0;
      let gyy = 0;
      let j = 0;
      for (let dy = -opt.half; dy <= opt.half; dy++)
        for (let dx = -opt.half; dx <= opt.half; dx++, j++) {
          const x = px + dx;
          const y = py + dy;
          ix[j] = (sample(a, x + 1, y) - sample(a, x - 1, y)) / 2;
          iy[j] = (sample(a, x, y + 1) - sample(a, x, y - 1)) / 2;
          ia[j] = sample(a, x, y);
          gxx += ix[j]! * ix[j]!;
          gxy += ix[j]! * iy[j]!;
          gyy += iy[j]! * iy[j]!;
        }
      const det = gxx * gyy - gxy * gxy;
      vx = 0;
      vy = 0;
      if (det > 1e-6) {
        for (let it = 0; it < opt.iters; it++) {
          let bx = 0;
          let by = 0;
          j = 0;
          for (let dy = -opt.half; dy <= opt.half; dy++)
            for (let dx = -opt.half; dx <= opt.half; dx++, j++) {
              const e = ia[j]! - sample(b, px + dx + gx + vx, py + dy + gy + vy);
              bx += e * ix[j]!;
              by += e * iy[j]!;
            }
          const ex = (gyy * bx - gxy * by) / det;
          const ey = (gxx * by - gxy * bx) / det;
          vx += ex;
          vy += ey;
          if (ex * ex + ey * ey < 1e-4) break;
        }
      }
      if (L === 0) {
        eig = (gxx + gyy - Math.sqrt((gxx - gyy) ** 2 + 4 * gxy * gxy)) / 2 / n;
        res = 0;
        j = 0;
        for (let dy = -opt.half; dy <= opt.half; dy++)
          for (let dx = -opt.half; dx <= opt.half; dx++, j++) res += Math.abs(ia[j]! - sample(b, px + dx + gx + vx, py + dy + gy + vy));
        res /= n;
      } else {
        gx = 2 * (gx + vx);
        gy = 2 * (gy + vy);
      }
    }
    out.push({ x: p.x + gx + vx, y: p.y + gy + vy });
    residual.push(res);
    minEig.push(eig);
  }
  return { pts: out, residual, minEig };
}

/**
 * A tracked point is kept only with enough texture, a close match and a plausible displacement.
 * Eyelid points are stricter: a closing lid covers the iris, the window's appearance changes and a
 * loose match follows the wrong structure (bench: eye error 0.025 strict vs 0.085 loose), while the
 * mouth corners deform a lot and need the looser match (smile 0.058 loose vs 0.071 strict).
 */
export const TRACK_TRUST = Object.freeze({
  loose: { minEig: 0.1, maxResidual: 20 },
  strict: { minEig: 0.5, maxResidual: 12 },
  maxShiftIpd: 0.3,
  /**
   * Largest disagreement with the same frame's detection (≈ 6 mm; units of the outer-canthal distance like
   * maxShiftIpd). The detection's bias is a few mm; in a broad smile the flow can jump 18–21 mm on the moving
   * cheek (phone, FPA-GEOM 0.4.0) and such a point is lost, not tracked.
   */
  maxOffDetectionIpd: 0.07,
});
const STRICT = new Set<number>([...CONTOURS.rightEye!, ...CONTOURS.leftEye!]);

/** Lips and nose base: the points a pucker or a snarl moves most. */
export const MOUTH_POINTS: ReadonlySet<number> = new Set<number>([...CONTOURS.lipsOuter!, ...CONTOURS.lipsInner!, ...CONTOURS.noseBase!]);

/**
 * Experiment switches for the mouth points (tools/eval methods 'trkM…'; the app uses none). The detection misreads
 * a pucker badly (bench: ratio error 0.83), so the off-detection check can throw out a correct track there.
 */
export interface TrackExperiment {
  /** Off-detection limit for MOUTH_POINTS (units as maxOffDetectionIpd); Infinity = no check. */
  mouthOffDetectionIpd?: number;
  /** Start the mouth points' flow at the detection instead of the rest position. */
  mouthGuessFromDetection?: boolean;
  /** Keep every tracked point (no trust checks, no detection fallback). */
  noTrust?: boolean;
  /** Crop size: outer-canthal distance in crop pixels (default CROP_IPD_PX). */
  cropIpd?: number;
  /** LK window half size and pyramid levels (default TRACK_DEFAULTS). */
  half?: number;
  levels?: number;
}

/** Face crop in reference-image pixels: crop px = scale · (p − origin). */
export interface Crop {
  x: number;
  y: number;
  w: number;
  h: number;
  scale: number;
}

/** Reference (rest) frame: its detection, crop and image pyramid. */
export interface TrackRef {
  obs: FrameObservation;
  crop: Crop;
  pyr: Gray[];
  /** The reference crop itself (unblurred), for the eye-closure mirror composites (mirror.ts). */
  gray?: Gray;
}

/**
 * Target inter-eye distance in the crop (larger faces are downsampled, smaller never upsampled). Bench:
 * 90 px lost skin detail (brow error 0.022, snarl 0.064) against 0.004 / 0.034 at 140 px.
 */
export const CROP_IPD_PX = 140;

/**
 * FPA-GEOM 0.6.0: the pucker task is tracked on a finer crop (280 px, never upsampled) with a 21 px window and 4 levels.
 * On real faces with a known truth (motion-attenuation synthesis, tools/bench/attenuate.py) plain LK followed the points
 * to 0.2 % of the eye distance while the 140 px crop lost the lip detail: pucker error 0.171 -> 0.014 on the rendered
 * face, 0.241 -> 0.112 on the own-photo synthesis. For the other tasks the same setting changed the errors by only
 * 0.01-0.03 either way at 2.6x the tracking time, so they stay as they were (tools/blender/BENCH.md).
 */
export const FINE_TRACK = Object.freeze({ cropIpd: 280, half: 10, levels: 4 });
export const FINE_TASKS: ReadonlySet<string> = new Set(['pucker']);

const px = (o: FrameObservation, i: number): Vec2 => ({ x: o.landmarks[3 * i]! * o.width, y: o.landmarks[3 * i + 1]! * o.height });

/** Face box × 1.5 around the rest detection, scaled so the eyes are ~CROP_IPD_PX apart (never upsampled). */
export function cropFor(obs: FrameObservation, ipdPx: number = CROP_IPD_PX): Crop {
  let [x0, y0, x1, y1] = [Infinity, Infinity, -Infinity, -Infinity];
  for (let i = 0; i < 468; i++) {
    const p = px(obs, i);
    [x0, y0, x1, y1] = [Math.min(x0, p.x), Math.min(y0, p.y), Math.max(x1, p.x), Math.max(y1, p.y)];
  }
  const ipd = Math.hypot(px(obs, 33).x - px(obs, 263).x, px(obs, 33).y - px(obs, 263).y);
  const scale = Math.min(1, ipdPx / Math.max(ipd, 1));
  const [cx, cy, hw, hh] = [(x0 + x1) / 2, (y0 + y1) / 2, ((x1 - x0) * 1.5) / 2, ((y1 - y0) * 1.5) / 2];
  return { x: cx - hw, y: cy - hh, w: Math.ceil(2 * hw * scale), h: Math.ceil(2 * hh * scale), scale };
}

/** Similarity taking the frame's pixels onto the reference's (fitted on the rigid anchors of both detections). */
export function toRef(ref: FrameObservation, obs: FrameObservation): Similarity {
  return fitSimilarity(
    ALIGNMENT_ANCHORS.map((i) => px(obs, i)),
    ALIGNMENT_ANCHORS.map((i) => px(ref, i)),
  );
}

/** Canvas transform [a, b, c, d, e, f] drawing the frame into the reference crop (undoing the head motion). */
export function cropTransform(crop: Crop, U: Similarity): [number, number, number, number, number, number] {
  const k = crop.scale * U.s;
  return [k * U.c, k * U.sn, -k * U.sn, k * U.c, crop.scale * (U.tx - crop.x), crop.scale * (U.ty - crop.y)];
}

function invert(U: Similarity): Similarity {
  // p' = s·R·p + t  →  p = R⁻¹(p' − t)/s
  const s = 1 / U.s;
  return { s, c: U.c, sn: -U.sn, tx: -s * (U.c * U.tx + U.sn * U.ty), ty: -s * (-U.sn * U.tx + U.c * U.ty) };
}

/**
 * Expression observation whose face-mesh points (0–467) are the reference detection tracked into
 * `B`, the expression frame drawn into the reference crop with `cropTransform(ref.crop, toRef(ref.obs, expr))`.
 * With the head motion already undone, the flow only has to find the expression itself.
 * Untrusted points (flat skin, a closing lid, a lost match) keep the detected position; iris points
 * (468+) follow the head only; pose and luminance stay those of the detection. `stats.kept` = tracked share.
 */
export function trackAligned(
  ref: TrackRef,
  expr: FrameObservation,
  B: Gray[],
  opt?: TrackOptions,
  stats?: { kept: number; lost?: number[] },
  exp?: TrackExperiment,
): FrameObservation {
  const { crop } = ref;
  const back = invert(toRef(ref.obs, expr)); // reference px → expression px
  const n = Math.min(468, Math.floor(ref.obs.landmarks.length / 3));
  const pts = Array.from({ length: n }, (_, i) => {
    const p = px(ref.obs, i);
    return { x: crop.scale * (p.x - crop.x), y: crop.scale * (p.y - crop.y) };
  });
  const fwd = toRef(ref.obs, expr); // expression px → reference px
  const det = (i: number): Vec2 => {
    const q = applySimilarity(fwd, px(expr, i));
    return { x: crop.scale * (q.x - crop.x), y: crop.scale * (q.y - crop.y) };
  };
  const guess = exp?.mouthGuessFromDetection ? pts.map((p, i) => (MOUTH_POINTS.has(i) ? det(i) : p)) : pts;
  const tr = trackPoints(ref.pyr, B, pts, guess, opt);
  const ipd = Math.hypot(pts[33]!.x - pts[263]!.x, pts[33]!.y - pts[263]!.y);
  const trusted = tr.pts.map((q, i) => {
    if (exp?.noTrust) return true;
    const th = STRICT.has(i) ? TRACK_TRUST.strict : TRACK_TRUST.loose;
    const d = det(i);
    return (
      tr.minEig[i]! >= th.minEig &&
      tr.residual[i]! <= th.maxResidual &&
      Math.hypot(q.x - pts[i]!.x, q.y - pts[i]!.y) <= TRACK_TRUST.maxShiftIpd * ipd &&
      Math.hypot(q.x - d.x, q.y - d.y) <=
        (MOUTH_POINTS.has(i) ? (exp?.mouthOffDetectionIpd ?? TRACK_TRUST.maxOffDetectionIpd) : TRACK_TRUST.maxOffDetectionIpd) * ipd
    );
  });
  if (stats) {
    stats.kept = trusted.filter(Boolean).length / Math.max(1, trusted.length);
    stats.lost = trusted.flatMap((ok, i) => (ok ? [] : [i]));
  }
  const lm = Array.from(expr.landmarks);
  const total = Math.floor(lm.length / 3);
  for (let i = 0; i < total; i++) {
    if (i < n && !trusted[i]) continue; // keep the detected point
    const r = i < n ? { x: tr.pts[i]!.x / crop.scale + crop.x, y: tr.pts[i]!.y / crop.scale + crop.y } : px(ref.obs, i);
    const q = applySimilarity(back, r);
    lm[3 * i] = q.x / expr.width;
    lm[3 * i + 1] = q.y / expr.height;
  }
  return { ...expr, landmarks: lm };
}
